mapper.select:
SELECT id, email, code_hash, purpose, expires_at, used_at, attempts, ip_address, created_at
FROM email_codes
WHERE email = #{email}
  AND purpose = #{purpose}
ORDER BY id DESC
LIMIT 1

mapper.update:
UPDATE email_codes
SET used_at = #{usedAt}
WHERE id = #{id}
  AND used_at IS NULL

UPDATE email_codes
SET attempts = attempts + 1
WHERE id = #{id}

mapper.select:
SELECT COUNT(*)
FROM email_codes
WHERE email = #{email}
  AND purpose = #{purpose}
  AND created_at >= #{since}
